go-int-overflow.solution:
def fixed_width(kind, start, ops):
    def info(k):
        if k.startswith("u"):
            return False, int(k[4:])
        return True, int(k[3:])

    def wrap(v, k):
        signed, bits = info(k)
        v &= (1 << bits) - 1
        if signed and v >= 1 << (bits - 1):
            v -= 1 << bits
        return v

    cur = wrap(start, kind)
    for op, x in ops:
        if op == "conv":
            kind = x
            cur = wrap(cur, kind)
            continue
        if op == "<<":
            cur = wrap(cur << x, kind)
            continue
        if op == ">>":
            cur = cur >> x
            continue
        y = wrap(x, kind)
        if op in ("/", "%") and y == 0:
            return "panic: runtime error: integer divide by zero"
        if op == "+":
            r = cur + y
        elif op == "-":
            r = cur - y
        elif op == "*":
            r = cur * y
        elif op == "/":
            r = abs(cur) // abs(y)
            if (cur < 0) != (y < 0):
                r = -r
        else:
            r = abs(cur) % abs(y)
            if cur < 0:
                r = -r
        cur = wrap(r, kind)
    return [kind, cur]

