go-slice-append-sim.solution:
def simulate(ops):
    s = {}
    nil = lambda: [[], 0, 0, 0]
    for op in ops:
        kind = op[0]
        if kind == "make":
            _, name, ln, cp = op
            s[name] = [[0] * cp, 0, ln, cp]
        elif kind == "append":
            dst, src, vals = op[1], op[2], list(op[3:])
            arr, off, ln, cp = s.get(src) or nil()
            need = ln + len(vals)
            if need <= cp:
                for i, v in enumerate(vals):
                    arr[off + ln + i] = v
                s[dst] = [arr, off, need, cp]
            else:
                if need > 2 * cp:
                    nc = need
                elif cp < 256:
                    nc = 2 * cp
                else:
                    nc = cp
                    while nc < need:
                        nc += (nc + 768) // 4
                new = arr[off:off + ln] + vals + [0] * (nc - need)
                s[dst] = [new, 0, need, nc]
        elif kind == "slice":
            _, dst, src, lo, hi = op
            arr, off, ln, cp = s.get(src) or nil()
            s[dst] = [arr, off + lo, hi - lo, cp - lo]
        elif kind == "set":
            _, name, i, v = op
            arr, off, ln, cp = s[name]
            arr[off + i] = v
        elif kind == "copy":
            d = s.get(op[1]) or nil()
            r = s.get(op[2]) or nil()
            n = min(d[2], r[2])
            tmp = r[0][r[1]:r[1] + n]
            d[0][d[1]:d[1] + n] = tmp
    return [[name, v[2], v[3], v[0][v[1]:v[1] + v[2]]] for name, v in sorted(s.items())]

