def run_map_ops(ops):
    m = None
    out = []
    for op in ops:
        kind = op[0]
        if kind == "make":
            m = {}
        elif kind in ("set", "inc"):
            if m is None:
                out.append("panic: assignment to entry in nil map")
                break
            if kind == "set":
                m[op[1]] = op[2]
            else:
                m[op[1]] = m.get(op[1], 0) + 1
        elif kind == "get":
            out.append((m or {}).get(op[1], 0))
        elif kind == "lookup":
            d = m or {}
            out.append([d.get(op[1], 0), op[1] in d])
        elif kind == "delete":
            if m is not None:
                m.pop(op[1], None)
        elif kind == "len":
            out.append(len(m or {}))
        elif kind == "clear":
            if m is not None:
                m.clear()
    return out

go-shadowing-scopes.solution:
def run_blocks(program):
    out = []

    class CompileError(Exception):
        pass

    def find(scopes, name):
        for sc in reversed(scopes):
            if name in sc:
                return sc
        raise CompileError()

    def run(stmts, outer):
        cur = {}
        scopes = outer + [cur]
        for st in stmts:
            kind = st[0]
            if kind == "var":
                if st[1] in cur:
                    raise CompileError()
                cur[st[1]] = st[2]
            elif kind == "short":
                names, vals = st[1], st[2]
                if all(n in cur for n in names):
                    raise CompileError()
                for n, v in zip(names, vals):
                    cur[n] = v
            elif kind == "assign":
                find(scopes, st[1])[st[1]] = st[2]
            elif kind == "add":
                find(scopes, st[1])[st[1]] += st[2]
            elif kind == "print":
                out.append(find(scopes, st[1])[st[1]])
            elif kind == "block":
                run(st[1], scopes)

    try:
        run(program, [])
    except CompileError:
        return "compile error"
    return out

guide.approach:
Recursive `run(statements, outer_scopes)` creates a fresh dictionary, pushes it and executes.

**Dry run** of the test `x := 1; { x, err := 5, 0; x += 10; print x }; print x`. Outer sheet `{x:1}`. Inside the
block, neither `x` nor `err` is on the *inner* sheet, so both are declared there: inner `{x:5, err:0}`.
`x += 10` finds the inner `x`: 15. Print 15. The block ends, the inner sheet is thrown away, and the outer
`x` is still 1. Output `[15, 1]`. This is the classic bug where the programmer meant to update the outer `x`.

**The same behaviour in Go:**

```go
package main

import (
	"fmt"
	"strconv"
)

func main() {
	x := 1
	{
		x, err := strconv.Atoi("5") // new x: shadows the outer one
		if err != nil {
			return
		}
		x += 10
		fmt.Println(x) // 15
	}
	fmt.Println(x) // 1: the outer x never changed
}
```

go-switch-fallthrough.solution:
def run_switch(tags, clauses):
    result = []
    for tag in tags:
        start = None
        default = None
        for i, (vals, _label, _ft) in enumerate(clauses):
            if vals is None:
                default = i
            elif start is None and tag in vals:
                start = i
        if start is None:
            start = default
        out = []
        i = start
        while i is not None:
            out.append(clauses[i][1])
            i = i + 1 if clauses[i][2] and i + 1 < len(clauses) else None
        result.append(out)
    return result

go-defer-order.solution:
def run_defers(stmts):
    env = {}
    out = []
    stack = []
    for st in stmts:
        kind = st[0]
        if kind == "set":
            env[st[1]] = st[2]
        elif kind == "add":
            env[st[1]] = env.get(st[1], 0) + st[2]
        elif kind == "print":
            out.append(env.get(st[1], 0))
        elif kind == "defer_print":
            stack.append(("value", env.get(st[1], 0)))
        elif kind == "defer_closure":
            stack.append(("read", st[1]))
        elif kind == "defer_add":
            stack.append(("add", st[1], st[2]))
        elif kind == "return":
            env["result"] = env.get(st[1], 0)
            break
    while stack:
        d = stack.pop()
        if d[0] == "value":
            out.append(d[1])
        elif d[0] == "read":
            out.append(env.get(d[1], 0))
        else:
            env[d[1]] = env.get(d[1], 0) + d[2]
    return [out, env.get("result", 0)]

go-escape-analysis.solution:
def escaping(stmts, big):
    pts = {}
    holds = {}

    def grow(table, key, items):
        cur = table.setdefault(key, set())
        before = len(cur)
        cur |= items
        return len(cur) != before

    changed = True
    while changed:
        changed = False
        for st in stmts:
            kind = st[0]
            if kind == "addr":
                changed |= grow(pts, st[1], {st[2]})
            elif kind == "assign":
                changed |= grow(pts, st[1], set(pts.get(st[2], ())))
            elif kind == "store_field":
                src = set(pts.get(st[2], ()))
                for t in list(pts.get(st[1], ())):
                    changed |= grow(holds, t, src)
            elif kind == "load_field":
                for t in list(pts.get(st[2], ())):
                    changed |= grow(pts, st[1], set(holds.get(t, ())))
    esc = set(big)
    for st in stmts:
        if st[0] in ("return", "store_global", "send", "go", "call_iface"):
            esc |= pts.get(st[1], set())
    stack = list(esc)
    while stack:
        t = stack.pop()
        for u in holds.get(t, ()):
            if u not in esc:
                esc.add(u)
                stack.append(u)
    return sorted(esc)

guide.approach:
Breadth-first search by levels. At each level collect every `(type, name)` hit for the selector. One hit:
done. Several: ambiguous. None: replace the level with all the types embedded by the current level.

**Dry run** (diamond): `D` embeds `L` and `R`, both embed `Base{ID}`. Query `D.ID`. Level 0 `[D]`: names are
`L, R`, no hit. Level 1 `[L, R]`: names `Base, Base`, no `ID`. Level 2 `[Base, Base]`: two hits → `"ambiguous"`.
Query `D.Base` is ambiguous too (two fields named `Base` at depth 1).

**The same behaviour in Go:**

```go
package main

import "fmt"

type Engine struct{ Power int }

func (e Engine) Start() string { return "vroom" }

type Radio struct{ Power int } // same field name as Engine.Power

type Car struct {
	Engine
	Radio
	Name string
}

func main() {
	c := Car{Engine{150}, Radio{5}, "Mini"}
	fmt.Println(c.Start())      // promoted method: vroom
	fmt.Println(c.Engine.Power) // 150: spell out the path
	// fmt.Println(c.Power)     // compile error: ambiguous selector c.Power
}
```

go-method-sets.solution:
def missing_methods(types, interfaces, queries):
    def mset(name, ptr):
        t = types.get(name, {})
        s = set(t.get("value", []))
        if ptr:
            s |= set(t.get("pointer", []))
        for e in t.get("embeds", []):
            if e.startswith("*"):
                s |= mset(e[1:], True)
            else:
                s |= mset(e, ptr)
        return s

    def wanted(iface, seen=()):
        need = set()
        for entry in interfaces.get(iface, []):
            if entry in interfaces and entry not in seen:
                need |= wanted(entry, seen + (iface,))
            else:
                need.add(entry)
        return need

    out = []
    for expr, iface in queries:
        ptr = expr.startswith("*")
        out.append(sorted(wanted(iface) - mset(expr.lstrip("*"), ptr)))
    return out

guide.approach:
`mset(T, ptr)` = value methods, plus pointer methods if `ptr`, plus for each embedded entry either
`mset(E, True)` (embedded pointer) or `mset(E, ptr)` (embedded value).

**Dry run:** `Inner{value:[V], pointer:[P]}`, `Outer` embeds `Inner`. `mset(Outer, False)` = `mset(Inner, False)` = `{V}`,
so `Outer` is missing `P` for interface `Both`. `mset(Outer, True)` = `{V, P}`. If `Outer` embedded `*Inner`
instead, both would be `{V, P}`.

**The same behaviour in Go:**

```go
package main

import "fmt"

type Shape interface{ Area() float64 }
type Scaler interface{ Scale(f float64) }

type Square struct{ side float64 }

func (s Square) Area() float64   { return s.side * s.side } // value receiver
func (s *Square) Scale(f float64) { s.side *= f }            // pointer receiver

func main() {
	var a Shape = Square{2}  // ok: Area is in the method set of Square
	var b Scaler = &Square{2} // ok: *Square has Scale
	// var c Scaler = Square{2}
	// compile error: Square does not implement Scaler (method Scale has pointer receiver)
	b.Scale(3)
	fmt.Println(a.Area(), b.(*Square).Area()) // 4 36
}
```

go-nil-interface.solution:
def eval_nil(stmts):
    kinds = {}
    vals = {}
    out = []
    counter = [0]

    def pair(name):
        return vals[name]

    for st in stmts:
        op = st[0]
        if op == "iface":
            kinds[st[1]] = "iface"
            vals[st[1]] = (None, None)
        elif op == "nilptr":
            kinds[st[1]] = "ptr"
            vals[st[1]] = ("*" + st[2], None)
        elif op == "newptr":
            counter[0] += 1
            kinds[st[1]] = "ptr"
            vals[st[1]] = ("*" + st[2], counter[0])
        elif op == "assign":
            dst, src = st[1], st[2]
            if kinds[dst] == "iface":
                vals[dst] = (None, None) if src == "nil" else vals[src]
            else:
                vals[dst] = (vals[dst][0], None if src == "nil" else vals[src][1])
        elif op == "isnil":
            t, v = vals[st[1]]
            out.append((t is None) if kinds[st[1]] == "iface" else (v is None))
        elif op == "eq":
            out.append(pair(st[1]) == pair(st[2]))
        elif op == "type":
            t, v = vals[st[1]]
            out.append("<nil>" if t is None else t)
        elif op == "call":
            t, v = vals[st[1]]
            if t is None:
                out.append("panic")
            elif v is None:
                out.append("ok" if st[2] == "safe" else "panic")
            else:
                out.append("ok")
    return out

guide.approach:
Use tuples. Pointer variable: `("*T", id-or-None)`. Interface: `(None, None)` or a copy of a pointer's tuple.
Equality is tuple equality.

**Dry run** of the example: `p = ("*MyErr", None)`, `err = (None, None)` → `isnil err` true. `err = p` copies the
tuple: `("*MyErr", None)`. `isnil p` → value is None → true. `isnil err` → type is not None → **false**.

**The same behaviour in Go:**

```go
package main

import "fmt"

type MyErr struct{ msg string }

func (e *MyErr) Error() string { return "boom" } // "safe": never touches e.msg

func find(fail bool) error {
	var p *MyErr // nil pointer
	if fail {
		p = &MyErr{"bad"}
	}
	return p // BUG: wraps a possibly-nil *MyErr in a non-nil error
}

func main() {
	err := find(false)
	fmt.Println(err == nil)        // false
	fmt.Printf("%T %v\n", err, err) // *main.MyErr boom
}
```

The fix is to return the literal `nil` on the success path, and to declare variables as `error`, not as
a concrete pointer type.

go-constraint-check.solution:
def satisfies(types, constraints, queries):
    def ok(t, c):
        info = types.get(t, {})
        under = info.get("underlying", t)
        methods = info.get("methods", [])
        if c == "any":
            return True
        if c == "comparable":
            return not (under.startswith("[]") or under.startswith("map[") or under.startswith("func"))
        d = constraints[c]
        for e in d.get("embeds", []):
            if not ok(t, e):
                return False
        terms = d.get("types", [])
        if terms:
            for term in terms:
                if term.startswith("~"):
                    if term[1:] == under:
                        break
                elif term == t:
                    break
            else:
                return False
        return all(m in methods for m in d.get("methods", []))

    return [ok(t, c) for t, c in queries]

guide.approach:
`ok(type, constraint)`: handle the two built-ins, then check embeds (recursively), terms, methods.

**Dry run:** `Celsius` (underlying `float64`) against `Exact = int | float64`. Terms have no tilde, so compare the
name `Celsius` with `int` and with `float64`: no match → false. Against `Number = ~int | ~float64`: compare the
underlying type `float64` with `int` (no), with `float64` (yes) → true.

**The same behaviour in Go:**

```go
package main

import "fmt"

type Number interface{ ~int | ~float64 }
type Exact interface{ int | float64 }

type Celsius float64

func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

func Double[T Exact](x T) T { return x * 2 }

func main() {
	fmt.Println(Sum([]Celsius{20.5, 1.5})) // 22: Celsius has underlying type float64
	fmt.Println(Double(21))                // 42
	// Double(Celsius(1))
	// compile error: Celsius does not satisfy Exact (possibly missing ~ for float64 in Exact)
}
```

go-error-chain.solution:
def error_queries(errors, queries):
    def children(e):
        w = errors[e].get("wraps")
        if w is None:
            return []
        return list(w) if isinstance(w, list) else [w]

    def walk(e):
        yield e
        for c in children(e):
            yield from walk(c)

    def msg(e):
        w = errors[e].get("wraps")
        if w is None:
            return errors[e]["msg"]
        if isinstance(w, list):
            return "\n".join(msg(c) for c in w)
        return errors[e]["msg"] + ": " + msg(w)

    out = []
    for q in queries:
        kind, e = q[0], q[1]
        if kind == "msg":
            out.append(msg(e))
        elif kind == "unwrap":
            w = errors[e].get("wraps")
            out.append(None if w is None or isinstance(w, list) else w)
        elif kind == "is":
            out.append(any(x == q[2] for x in walk(e)))
        elif kind == "as":
            out.append(next((x for x in walk(e) if errors[x]["type"] == q[2]), None))
    return out

guide.approach:
Recursive pre-order walk plus a recursive message builder.

**Dry run:** `j = Join(w1, t2)` where `w1` wraps `t1`. Walk order: `j, w1, t1, t2`. `as j Timeout` → `t1` (found
inside `w1` before `t2` is visited). Swap the join's children and the answer becomes `t2`.

**The same behaviour in Go:**

```go
package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found") // sentinel: compared by identity

type QueryError struct {
	Table string
	Err   error
}

func (q *QueryError) Error() string { return "query " + q.Table + ": " + q.Err.Error() }
func (q *QueryError) Unwrap() error { return q.Err }

func main() {
	err := fmt.Errorf("handler: %w", &QueryError{"users", ErrNotFound})
	fmt.Println(err)                         // handler: query users: not found
	fmt.Println(errors.Is(err, ErrNotFound)) // true

	var qe *QueryError
	if errors.As(err, &qe) {
		fmt.Println(qe.Table) // users
	}
	both := errors.Join(err, errors.New("also failed"))
	fmt.Println(errors.Unwrap(both) == nil) // true: Join exposes Unwrap() []error instead
}
```

go-import-path-version.solution:
import re

def release(base, version, changes):
    m = re.fullmatch(r"v(0|[1-9][0-9]*)[.](0|[1-9][0-9]*)[.](0|[1-9][0-9]*)", version)
    if not m:
        return "invalid"
    major, minor, patch = (int(g) for g in m.groups())
    for c in changes:
        if c == "fix":
            patch += 1
        elif c == "feature":
            minor, patch = minor + 1, 0
        elif c == "breaking":
            if major == 0:
                minor, patch = minor + 1, 0
            else:
                major, minor, patch = major + 1, 0, 0
        elif c == "stable":
            if major == 0:
                major, minor, patch = 1, 0, 0
    path = base if major < 2 else "%s/v%d" % (base, major)
    return ["v%d.%d.%d" % (major, minor, patch), path]

go-mvs.solution:
def build_list(root_reqs, graph):
    def key(v):
        return tuple(int(x) for x in v[1:].split("."))

    best = {}
    seen = set()
    stack = list(root_reqs)
    while stack:
        mv = stack.pop()
        if mv in seen:
            continue
        seen.add(mv)
        mod, ver = mv.rsplit("@", 1)
        if mod not in best or key(ver) > key(best[mod]):
            best[mod] = ver
        stack.extend(graph.get(mv, []))
    return sorted("%s@%s" % (m, v) for m, v in best.items())

go-build-constraint.solution:
import re

KNOWN_OS = {"linux", "windows", "darwin", "freebsd", "android", "ios", "js", "wasip1"}
KNOWN_ARCH = {"amd64", "arm64", "386", "arm", "wasm", "riscv64"}
UNIX = {"linux", "darwin", "freebsd", "android", "ios"}


def file_included(filename, expr, goos, goarch, tags):
    name = filename[:-3] if filename.endswith(".go") else filename
    if name.endswith("_test"):
        name = name[:-5]
    if "_" in name:
        parts = name.split("_")[1:]
        n = len(parts)
        if n >= 2 and parts[-2] in KNOWN_OS and parts[-1] in KNOWN_ARCH:
            if parts[-2] != goos or parts[-1] != goarch:
                return False
        elif parts[-1] in KNOWN_OS:
            if parts[-1] != goos:
                return False
        elif parts[-1] in KNOWN_ARCH:
            if parts[-1] != goarch:
                return False
    if expr is None:
        return True

    true_tags = set(tags) | {goos, goarch}
    if goos in UNIX:
        true_tags.add("unix")
    toks = re.findall(r"[(]|[)]|&&|[|][|]|!|[A-Za-z0-9_.]+", expr)
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def take():
        pos[0] += 1
        return toks[pos[0] - 1]

    def parse_or():
        v = parse_and()
        while peek() == "||":
            take()
            r = parse_and()
            v = v or r
        return v

    def parse_and():
        v = parse_not()
        while peek() == "&&":
            take()
            r = parse_not()
            v = v and r
        return v

    def parse_not():
        if peek() == "!":
            take()
            return not parse_not()
        if peek() == "(":
            take()
            v = parse_or()
            take()
            return v
        return take() in true_tags

    return parse_or()

