def tag_lookup(tag, keys):
    found = {}
    i, n = 0, len(tag)
    while i < n:
        while i < n and tag[i] == " ":
            i += 1
        if i >= n:
            break
        j = i
        while j < n and tag[j] > " " and tag[j] not in ':"' and tag[j] != "\x7f":
            j += 1
        if j == i or j + 1 >= n or tag[j] != ":" or tag[j + 1] != '"':
            break
        name = tag[i:j]
        k = j + 2
        buf = []
        closed = False
        while k < n:
            ch = tag[k]
            if ch == '"':
                closed = True
                break
            if ch == "\\":
                k += 1
                if k >= n:
                    break
                esc = tag[k]
                buf.append({"n": "\n", "t": "\t"}.get(esc, esc))
            else:
                buf.append(ch)
            k += 1
        if not closed:
            break
        if name not in found:
            found[name] = "".join(buf)
        i = k + 1
    return [[found[k], True] if k in found else ["", False] for k in keys]

