go-gmp-scheduler.solution:
def gmp(local, global_q, quantum, global_every):
    local = [[list(g) for g in q] for q in local]
    glob = [list(g) for g in global_q]
    n = len(local)
    trace = []
    finished = {}
    rnd = 0
    while n and (glob or any(local)):
        rnd += 1
        running = []
        for p in range(n):
            g = None
            if rnd % global_every == 0 and glob:
                g = glob.pop(0)
            elif local[p]:
                g = local[p].pop(0)
            elif glob:
                g = glob.pop(0)
            else:
                victim = max(range(n), key=lambda v: (len(local[v]), -v))
                if local[victim]:
                    k = (len(local[victim]) + 1) // 2
                    stolen = local[victim][:k]
                    local[victim] = local[victim][k:]
                    g = stolen[0]
                    local[p].extend(stolen[1:])
            running.append(g)
        row = []
        for p, g in enumerate(running):
            if g is None:
                row.append(None)
                continue
            row.append(g[0])
            g[1] -= quantum
            if g[1] <= 0:
                finished[g[0]] = rnd
            else:
                local[p].append(g)
        trace.append(row)
    return [trace, [[gid, r] for gid, r in sorted(finished.items())]]

go-context-tree.solution:
def context_states(nodes, cancels):
    first_cancel = {}
    for cid, t in cancels:
        if cid not in first_cancel or t < first_cancel[cid]:
            first_cancel[cid] = t
    state = {}
    out = []
    for cid, parent, deadline in nodes:
        p_done, p_err, p_deadline = state[parent] if parent is not None else (None, None, None)
        if deadline is None:
            eff = p_deadline
        elif p_deadline is None:
            eff = deadline
        else:
            eff = min(deadline, p_deadline)
        candidates = []
        if p_done is not None:
            candidates.append((p_done, 0, p_err))
        if cid in first_cancel:
            candidates.append((first_cancel[cid], 1, "context canceled"))
        if deadline is not None:
            candidates.append((deadline, 2, "context deadline exceeded"))
        if candidates:
            t, _, err = min(candidates)
        else:
            t, err = None, None
        state[cid] = (t, err, eff)
        out.append([cid, t, err, eff])
    return out

go-json-tags.solution:
import json


def marshal(fields):
    def is_struct(v):
        return isinstance(v, dict) and "__struct__" in v

    def empty(v):
        if v is None or v is False:
            return True
        if is_struct(v):
            return False
        if isinstance(v, bool):
            return False
        if isinstance(v, int):
            return v == 0
        return len(v) == 0

    def enc(v):
        if is_struct(v):
            return obj(v["__struct__"])
        if isinstance(v, dict):
            return "{" + ",".join(json.dumps(k) + ":" + enc(v[k]) for k in sorted(v)) + "}"
        if isinstance(v, list):
            return "[" + ",".join(enc(x) for x in v) + "]"
        return json.dumps(v)

    def obj(fs):
        parts = []
        for name, tag, val in fs:
            if not name[:1].isupper():
                continue
            if tag == "-":
                continue
            pieces = tag.split(",")
            key = pieces[0] or name
            opts = pieces[1:]
            if "omitempty" in opts and empty(val):
                continue
            text = enc(val)
            if "string" in opts and isinstance(val, int):
                text = json.dumps(text)
            parts.append(json.dumps(key) + ":" + text)
        return "{" + ",".join(parts) + "}"

    return obj(fields)

go-table-test-summary.solution:
def test_report(results):
    order = []
    subs = {}
    own = {}
    counts = {}
    for top, sub, outcome in results:
        if top not in subs:
            order.append(top)
            subs[top] = []
            own[top] = None
            counts[top] = {}
        if sub is None:
            own[top] = outcome
            continue
        name = sub.replace(" ", "_")
        seen = counts[top].get(name, 0)
        counts[top][name] = seen + 1
        if seen:
            name = "%s#%02d" % (name, seen)
        subs[top].append((name, outcome))
    lines = []
    failed = False
    for top in order:
        if subs[top]:
            status = "FAIL" if any(o == "fail" for _, o in subs[top]) else "PASS"
        else:
            status = (own[top] or "pass").upper()
        failed = failed or status == "FAIL"
        lines.append("--- %s: %s" % (status, top))
        for name, o in subs[top]:
            lines.append("    --- %s: %s/%s" % (o.upper(), top, name))
    lines.append("FAIL" if failed else "PASS")
    return lines

