go-real-rotate-left.solution:
package main

// RotateLeft returns a rotated copy of xs.
func RotateLeft(xs []int, k int) []int {
	n := len(xs)
	out := make([]int, 0, n)
	if n == 0 {
		return out
	}
	k %= n
	out = append(out, xs[k:]...)
	out = append(out, xs[:k]...)
	return out
}

