go-real-shapes.solution:
package main

import "math"

// Shape is anything with an area and a name.
type Shape interface {
	Area() float64
	Name() string
}

// Circle is a circle of radius R.
type Circle struct{ R float64 }

// Square is a square of side S.
type Square struct{ S float64 }

func (c Circle) Area() float64 { return math.Pi * c.R * c.R }
func (c Circle) Name() string  { return "circle" }
func (s Square) Area() float64 { return s.S * s.S }
func (s Square) Name() string  { return "square" }

// TotalArea sums the areas.
func TotalArea(shapes []Shape) float64 {
	total := 0.0
	for _, s := range shapes {
		total += s.Area()
	}
	return total
}

// Largest returns the shape with the largest area, or nil.
func Largest(shapes []Shape) Shape {
	var best Shape
	for _, s := range shapes {
		if best == nil || s.Area() > best.Area() {
			best = s
		}
	}
	return best
}

