package main

import "fmt"

// Money is an amount in cents.
type Money int64

// String formats m as dollars and cents.
func (m Money) String() string {
	sign := ""
	v := int64(m)
	if v < 0 {
		sign = "-"
		v = -v
	}
	return fmt.Sprintf("%s$%d.%02d", sign, v/100, v%100)
}

// Total sums the items.
func Total(items []Money) Money {
	var sum Money
	for _, it := range items {
		sum += it
	}
	return sum
}

