go-real-error-as.solution:
package main

import "fmt"

// ValidationError describes one invalid field.
type ValidationError struct {
	Field  string
	Reason string
}

func (e *ValidationError) Error() string { return e.Field + ": " + e.Reason }

func invalid(field, reason string) error {
	return fmt.Errorf("validate user: %w", &ValidationError{Field: field, Reason: reason})
}

// ValidateUser checks a name and an age.
func ValidateUser(name string, age int) error {
	switch {
	case name == "":
		return invalid("name", "is required")
	case age < 0:
		return invalid("age", "must not be negative")
	case age > 150:
		return invalid("age", "is unrealistic")
	}
	return nil
}

