package main

import "sync"

// ParallelMap applies f to every element concurrently and keeps the input order.
func ParallelMap(xs []int, f func(int) int) []int {
	out := make([]int, len(xs))
	var wg sync.WaitGroup
	for i, x := range xs {
		wg.Add(1)
		go func(i, x int) {
			defer wg.Done()
			out[i] = f(x) // each goroutine writes its own element
		}(i, x)
	}
	wg.Wait()
	return out
}

