import "sync"

// SafeCounter is a counter that may be used from many goroutines.
type SafeCounter struct {
	mu sync.Mutex // protects n
	n  int
}

// Inc adds one.
func (c *SafeCounter) Inc() { c.Add(1) }

// Add adds n.
func (c *SafeCounter) Add(n int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n += n
}

// Value returns the current total.
func (c *SafeCounter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

