package main

import "sync"

// ProcessAll runs f on every job using a fixed number of worker goroutines.
func ProcessAll(jobs []int, workers int, f func(int) int) []int {
	out := make([]int, len(jobs))
	indexes := make(chan int)

	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range indexes { // ends when indexes is closed
				out[i] = f(jobs[i])
			}
		}()
	}

	for i := range jobs {
		indexes <- i
	}
	close(indexes)
	wg.Wait()
	return out
}

