// meter records how many calls of slow run at the same time.
type meter struct {
	cur, max, calls atomic.Int64
}

func (m *meter) slow(n int) int {
	c := m.cur.Add(1)
	for {
		old := m.max.Load()
		if c <= old || m.max.CompareAndSwap(old, c) {
			break
		}
	}
	m.calls.Add(1)
	time.Sleep(15 * time.Millisecond)
	m.cur.Add(-1)
	return n * 10
}

