package main

import (
	"context"
	"time"
)

// WaitOrCancel waits for d, or returns early with ctx.Err() if ctx ends first.
func WaitOrCancel(ctx context.Context, d time.Duration) error {
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

