go-real-valid-parens.solution:
package main

// IsValid reports whether the brackets in s are balanced.
func IsValid(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	var stack []rune
	for _, r := range s {
		open, isClosing := pairs[r]
		if !isClosing {
			stack = append(stack, r)
			continue
		}
		if len(stack) == 0 || stack[len(stack)-1] != open {
			return false
		}
		stack = stack[:len(stack)-1]
	}
	return len(stack) == 0
}

