go-real-reverse-list.solution:
package main

// Node is an element of a singly linked list.
type Node struct {
	Val  int
	Next *Node
}

// Reverse reverses the list and returns its new head.
func Reverse(head *Node) *Node {
	var prev *Node
	for cur := head; cur != nil; {
		next := cur.Next
		cur.Next = prev
		prev, cur = cur, next
	}
	return prev
}

