func build(vals ...int) *Node {
	var head, tail *Node
	for _, v := range vals {
		n := &Node{Val: v}
		if head == nil {
			head, tail = n, n
		} else {
			tail.Next = n
			tail = n
		}
	}
	return head
}

func values(head *Node) []int {
	out := []int{}
	for n, steps := head, 0; n != nil && steps < 100000; n, steps = n.Next, steps+1 {
		out = append(out, n.Val)
	}
	return out
}

