go-real-two-sum.solution:
package main

// TwoSum returns the indexes of two values that add up to target.
func TwoSum(nums []int, target int) []int {
	seen := make(map[int]int, len(nums)) // value -> index where it was first seen
	for j, x := range nums {
		if i, ok := seen[target-x]; ok {
			return []int{i, j}
		}
		if _, dup := seen[x]; !dup {
			seen[x] = j
		}
	}
	return nil
}

